 */
@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class DayOfMonth_ESTest extends DayOfMonth_ESTest_scaffolding {

  /** The day-of-month produced by the fixed mock clock used in this suite. */
  private static final int MOCKED_TODAY = 14;

  @Test(timeout = 4000)
  public void of_withZeroDay_throwsDateTimeException()  throws Throwable  {
      // 0 is below the valid range (1..31), so construction must fail.
      try {
        DayOfMonth.of(0);
        fail("Expecting exception: DateTimeException");

      } catch(DateTimeException e) {
         // Invalid value for DayOfMonth: 0
         verifyException("org.threeten.extra.DayOfMonth", e);
      }
  }

  @Test(timeout = 4000)
  public void from_withZoneOffset_throwsDateTimeException()  throws Throwable  {
      // A ZoneOffset carries no day-of-month field, so extraction is impossible.
      ZoneOffset zoneOffset = ZoneOffset.MAX;
      try {
        DayOfMonth.from(zoneOffset);
        fail("Expecting exception: DateTimeException");

      } catch(DateTimeException e) {
         // Unable to obtain DayOfMonth from TemporalAccessor: +18:00 of type java.time.ZoneOffset
         verifyException("org.threeten.extra.DayOfMonth", e);
      }
  }

  @Test(timeout = 4000)
  public void equals_withDifferentDay_returnsFalse()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();
      DayOfMonth firstOfMonth = DayOfMonth.of(1);

      assertFalse(today.equals(firstOfMonth));
      assertEquals(MOCKED_TODAY, today.getValue());
      // equals is symmetric: the reverse comparison is also false.
      assertFalse(firstOfMonth.equals((Object) today));
  }

  @Test(timeout = 4000)
  public void equals_withSameInstance_returnsTrue()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      assertTrue(today.equals(today));
      assertEquals(MOCKED_TODAY, today.getValue());
  }

  @Test(timeout = 4000)
  public void equals_withUnrelatedType_returnsFalse()  throws Throwable  {
      OffsetDateTime offsetDateTime = MockOffsetDateTime.now();
      DayOfMonth dayOfMonth = DayOfMonth.from(offsetDateTime);

      // A ChronoField is not a DayOfMonth, so equals must be false.
      assertFalse(dayOfMonth.equals(ChronoField.MICRO_OF_SECOND));
      assertEquals(MOCKED_TODAY, dayOfMonth.getValue());
  }

  @Test(timeout = 4000)
  public void adjustInto_withNonIsoDate_throwsDateTimeException()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();
      Clock utcClock = MockClock.systemUTC();
      JapaneseDate japaneseDate = MockJapaneseDate.now(utcClock);

      // adjustInto only supports the ISO calendar system.
      try {
        today.adjustInto(japaneseDate);
        fail("Expecting exception: DateTimeException");

      } catch(DateTimeException e) {
         // Adjustment only supported on ISO date-time
         verifyException("org.threeten.extra.DayOfMonth", e);
      }
  }

  @Test(timeout = 4000)
  public void adjustInto_withIsoDateTime_returnsSameInstanceWhenDayUnchanged()  throws Throwable  {
      Clock utcClock = MockClock.system(ZoneOffset.UTC);
      LocalDateTime localDateTime = MockLocalDateTime.now(utcClock);
      DayOfMonth dayOfMonth = DayOfMonth.from(localDateTime);

      // Adjusting to the day it already has leaves the temporal unchanged.
      Temporal adjusted = dayOfMonth.adjustInto(localDateTime);
      assertSame(adjusted, localDateTime);
  }

  @Test(timeout = 4000)
  public void minguoDateFrom_dayOfMonth_throwsDateTimeException()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      // A DayOfMonth lacks the year/month needed to build a full date.
      try {
        MockMinguoDate.from(today);
        fail("Expecting exception: DateTimeException");

      } catch(DateTimeException e) {
         // Unable to obtain LocalDate from TemporalAccessor: DayOfMonth:14 of type org.threeten.extra.DayOfMonth
         verifyException("java.time.LocalDate", e);
      }
  }

  @Test(timeout = 4000)
  public void isValidYearMonth_day31_returnsFalseForShortMonth()  throws Throwable  {
      DayOfMonth day31 = DayOfMonth.of(31);
      YearMonth currentYearMonth = MockYearMonth.now();

      // The mocked month does not have 31 days, so day 31 is invalid for it.
      assertFalse(day31.isValidYearMonth(currentYearMonth));
      assertEquals(31, day31.getValue());
  }

  @Test(timeout = 4000)
  public void isValidYearMonth_day14_returnsTrue()  throws Throwable  {
      OffsetDateTime offsetDateTime = MockOffsetDateTime.now();
      DayOfMonth day14 = DayOfMonth.from(offsetDateTime);
      YearMonth currentYearMonth = MockYearMonth.now();

      // Day 14 fits in any month.
      assertTrue(day14.isValidYearMonth(currentYearMonth));
      assertEquals(MOCKED_TODAY, day14.getValue());
  }

  @Test(timeout = 4000)
  public void isValidYearMonth_withNull_returnsFalse()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      assertFalse(today.isValidYearMonth((YearMonth) null));
      assertEquals(MOCKED_TODAY, today.getValue());
  }

  @Test(timeout = 4000)
  public void hijrahDateFrom_dayOfMonth_throwsUnsupportedTemporalType()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      // Converting to a HijrahDate needs the EpochDay field, which is unsupported.
      try {
        MockHijrahDate.from(today);
        fail("Expecting exception: UnsupportedTemporalTypeException");

      } catch(UnsupportedTemporalTypeException e) {
         // Unsupported field: EpochDay
         verifyException("org.threeten.extra.DayOfMonth", e);
      }
  }

