  public void getLong_dayOfMonthField_returnsDayValue()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      assertEquals(14L, today.getLong(ChronoField.DAY_OF_MONTH));
  }

  @Test(timeout = 4000)
  public void getLong_withNullField_throwsNullPointerException()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      try {
        today.getLong((TemporalField) null);
        fail("Expecting exception: NullPointerException");

      } catch(NullPointerException e) {
         // no message in exception (getMessage() returned null)
         verifyException("org.threeten.extra.DayOfMonth", e);
      }
  }

  @Test(timeout = 4000)
  public void isSupported_dayOfMonthField_returnsTrue()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      assertTrue(today.isSupported(ChronoField.DAY_OF_MONTH));
      assertEquals(MOCKED_TODAY, today.getValue());
  }

  @Test(timeout = 4000)
  public void isSupported_withNullField_returnsFalse()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      assertFalse(today.isSupported((TemporalField) null));
      assertEquals(MOCKED_TODAY, today.getValue());
  }

  @Test(timeout = 4000)
  public void from_thaiBuddhistDate_extractsDayOfMonth()  throws Throwable  {
