      DayOfMonth dayOfMonth = DayOfMonth.from(thaiBuddhistDate);

      assertEquals(MOCKED_TODAY, dayOfMonth.getValue());
  }

  @Test(timeout = 4000)
  public void from_dayOfMonth_returnsEquivalentValue()  throws Throwable  {
