      DayOfMonth today = DayOfMonth.now();
      DayOfMonth copy = DayOfMonth.from(today);

      assertEquals(MOCKED_TODAY, copy.getValue());
  }

  @Test(timeout = 4000)
  public void atMonth_withMonthEnum_leavesDayUnchanged()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      today.atMonth(Month.JANUARY);
      // atMonth is non-mutating; the original day is preserved.
      assertEquals(MOCKED_TODAY, today.getValue());
  }

  @Test(timeout = 4000)
  public void now_withZoneId_returnsMockedToday()  throws Throwable  {
      ZoneId zone = ZoneOffset.ofHoursMinutes(1, 1);
      DayOfMonth today = DayOfMonth.now(zone);

      assertEquals(MOCKED_TODAY, today.getValue());
