  @Test(timeout = 4000)
  public void atYearMonth_leavesDayUnchanged()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();
      YearMonth currentYearMonth = MockYearMonth.now();

      today.atYearMonth(currentYearMonth);
      // atYearMonth is non-mutating; the original day is preserved.
      assertEquals(MOCKED_TODAY, today.getValue());
  }

  @Test(timeout = 4000)
  public void atMonth_withInvalidMonthNumber_throwsDateTimeException()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      // -2313 is not a valid month-of-year value.
      try {
        today.atMonth((-2313));
        fail("Expecting exception: DateTimeException");

      } catch(DateTimeException e) {
         // Invalid value for MonthOfYear: -2313
         verifyException("java.time.Month", e);
      }
  }

  @Test(timeout = 4000)
  public void getValue_returnsMockedToday()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      assertEquals(MOCKED_TODAY, today.getValue());
  }

  @Test(timeout = 4000)
  public void hashCode_canBeComputed()  throws Throwable  {
      Clock utcClock = MockClock.system(ZoneOffset.UTC);
      LocalDateTime localDateTime = MockLocalDateTime.now(utcClock);
      DayOfMonth dayOfMonth = DayOfMonth.from(localDateTime);

      dayOfMonth.hashCode();
      assertEquals(MOCKED_TODAY, dayOfMonth.getValue());
  }

  @Test(timeout = 4000)
  public void compareTo_sameInstance_returnsZero()  throws Throwable  {
      OffsetDateTime offsetDateTime = MockOffsetDateTime.now();
      DayOfMonth dayOfMonth = DayOfMonth.from(offsetDateTime);

      assertEquals(0, dayOfMonth.compareTo(dayOfMonth));
      assertEquals(MOCKED_TODAY, dayOfMonth.getValue());
  }

  @Test(timeout = 4000)
  public void yearMonthFrom_dayOfMonth_throwsDateTimeException()  throws Throwable  {
      DayOfMonth today = DayOfMonth.now();

      // A DayOfMonth has no year or month, so YearMonth cannot be derived.
      try {
        MockYearMonth.from(today);
        fail("Expecting exception: DateTimeException");

      } catch(DateTimeException e) {
         // Unable to obtain YearMonth from TemporalAccessor: DayOfMonth:14 of type org.threeten.extra.DayOfMonth
         verifyException("java.time.YearMonth", e);
      }
  }
